import inspect
from solution import find_rect_num


def test_issue_example_4_equals_20():
    """Example: assert find_rect_num(4) == 20."""
    assert find_rect_num(4) == 20  # 4*(4+1)=4*5=20


def test_issue_n0_equals_0():
    """n-th rectangular number with n=0 is 0."""
    assert find_rect_num(0) == 0  # 0*(0+1)=0*1=0


def test_issue_n1_equals_2():
    """n-th rectangular number with n=1 is 2."""
    assert find_rect_num(1) == 2  # 1*(1+1)=1*2=2


def test_issue_n2_equals_6():
    """n-th rectangular number with n=2 is 6."""
    assert find_rect_num(2) == 6  # 2*(2+1)=2*3=6


def test_issue_n3_equals_12():
    """n-th rectangular number just below example n=3 is 12."""
    assert find_rect_num(3) == 12  # 3*(3+1)=3*4=12


def test_issue_n5_equals_30():
    """n-th rectangular number just above example n=5 is 30."""
    assert find_rect_num(5) == 30  # 5*(5+1)=5*6=30


def test_issue_n7_equals_56():
    """n-th rectangular number with n=7 is 56."""
    assert find_rect_num(7) == 56  # 7*(7+1)=7*8=56


def test_issue_n10_equals_110():
    """n-th rectangular number with n=10 is 110."""
    assert find_rect_num(10) == 110  # 10*(10+1)=10*11=110


def test_issue_n100_equals_10200():
    """n-th rectangular number with large n=100 is 10200."""
    assert find_rect_num(100) == 10200  # 100*(100+1)=100*101=10200


def test_contract_callable_in_solution():
    """Public interface shows find_rect_num in solution."""
    assert callable(find_rect_num)


def test_contract_signature_single_param_n():
    """Public interface shows def find_rect_num(n)."""
    assert list(inspect.signature(find_rect_num).parameters) == ["n"]  # expected single param named n


def test_contract_returns_int():
    """Example shows find_rect_num(4) == 20 as int."""
    assert isinstance(find_rect_num(4), int)
